function getPos(item){const w=item.word,h=getHint(w).toLowerCase();if(POS_OVERRIDES[w])return POS_OVERRIDES[w];if(w.includes(' '))return 'phrase';if(/^to\s/.test(h))return 'verb';if(/ly$/.test(w))return 'adverb';if(/(tion|sion|ment|ness|ity|ism|ist|ance|ence|ship|hood|acy|age)$/.test(w))return 'noun';if(/(ous|ful|less|able|ible|ive|al|ic|ary|ory|ent|ant)$/.test(w))return 'adjective';if(/ed$/.test(w))return 'verb / adjective';if(/ing$/.test(w))return 'verb / noun';if(/s$/.test(w)&&!/(ss|us)$/.test(w))return 'noun / verb';if(/^(a |an |the |one |someone|something|people|the process|the act|the state|the quality)/.test(h))return 'noun';return 'noun / verb'}
function topicOf(item){return TOPICS.find(t=>item.id>=t.start&&item.id<t.end)}
function unlearned(topic){return topic.items.filter(x=>!learned.has(x.word))}
const speechState={voice:null,utterance:null,primed:false};
function cleanSpeechText(text){return String(text??'').replace(/\s*\(verb\)\s*$/i,'').replace(/[<>]/g,' ').replace(/\s+/g,' ').trim().slice(0,320)}
function isAppleEloquenceVoice(v){const id=((v?.voiceURI||'')+' '+(v?.name||'')).toLowerCase();return id.includes('eloquence')}
function chooseEnglishVoice(){if(!('speechSynthesis'in window))return null;const voices=window.speechSynthesis.getVoices();if(!voices.length)return speechState.voice;const english=voices.filter(v=>/^en(?:-|$)/i.test(v.lang)&&!isAppleEloquenceVoice(v));const preferred=english.find(v=>/^en-US$/i.test(v.lang)&&/com\.apple\.voice\.compact/i.test(v.voiceURI||''))||english.find(v=>/^en-US$/i.test(v.lang)&&v.localService)||english.find(v=>/^en-US$/i.test(v.lang))||english.find(v=>v.localService)||english[0]||null;speechState.voice=preferred;return preferred}
function primeSpeech(){if(!('speechSynthesis'in window)||speechState.primed)return;speechState.primed=true;chooseEnglishVoice()}
if('speechSynthesis'in window){chooseEnglishVoice();window.speechSynthesis.addEventListener?.('voiceschanged',chooseEnglishVoice)}
function speak(text){if(!('speechSynthesis'in window)||typeof SpeechSynthesisUtterance==='undefined')return;const clean=cleanSpeechText(text);if(!clean)return;const synth=window.speechSynthesis,voice=chooseEnglishVoice();try{if(synth.speaking||synth.pending)synth.cancel()}catch{}const u=new SpeechSynthesisUtterance(clean);u.lang='en-US';if(voice&&!isAppleEloquenceVoice(voice))u.voice=voice;u.rate=.82;u.pitch=1;u.volume=1;speechState.utterance=u;const release=()=>{if(speechState.utterance===u)speechState.utterance=null};u.onend=release;u.onerror=release;try{synth.speak(u)}catch{release()}}
let mode='quiz',activeTopic=0,queue=[],cursor=0,roundNo=1,answered=false,firstAttempt=true,dictWrongThisRound=false;
let synLesson=0,synRound=0,synQueue=[],synPair=null,synSelected=[],synLocked=false;const SYN_SIZE=10;const SYN_LESSONS=Array.from({length:Math.ceil(SYNONYMS.length/SYN_SIZE)},(_,i)=>SYNONYMS.slice(i*SYN_SIZE,(i+1)*SYN_SIZE));
function renderSidebar(){const list=$('#sideList'),sel=$('#mobileSelect');if(mode==='syn'){$('#sideTitle').textContent='Bài đồng nghĩa';$('#sideCount').textContent=`${SYN_LESSONS.length} bài`;list.innerHTML=SYN_LESSONS.map((x,i)=>`<button class="side-btn ${i===synLesson?'active':''}" data-i="${i}"><strong>Bài ${String(i+1).padStart(2,'0')}</strong><small>${x.length} cặp</small></button>`).join('');sel.innerHTML=SYN_LESSONS.map((x,i)=>`<option value="${i}" ${i===synLesson?'selected':''}>Bài ${String(i+1).padStart(2,'0')} · ${x.length} cặp</option>`).join('');$('#mobileLabel').textContent='Bài đồng nghĩa';list.querySelectorAll('button').forEach(b=>b.onclick=()=>selectSynLesson(+b.dataset.i));sel.onchange=()=>selectSynLesson(+sel.value)}else{$('#sideTitle').textContent='Chủ đề';$('#sideCount').textContent=`${TOPICS.length} nhóm`;list.innerHTML=TOPICS.map((t,i)=>{const left=unlearned(t).length,done=t.items.length-left;return `<button class="side-btn ${i===activeTopic?'active':''}" data-i="${i}"><strong>${t.name}</strong><small>${done}/${t.items.length} đã thuộc · còn ${left}</small></button>`}).join('');sel.innerHTML=TOPICS.map((t,i)=>`<option value="${i}" ${i===activeTopic?'selected':''}>${t.name} · còn ${unlearned(t).length}</option>`).join('');$('#mobileLabel').textContent='Chủ đề';list.querySelectorAll('button').forEach(b=>b.onclick=()=>selectTopic(+b.dataset.i));sel.onchange=()=>selectTopic(+sel.value)}}
function setMode(m){mode=m;$$('.tab').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));renderSidebar();if(m==='syn')renderSynStart();else renderTopicStart()}
function selectTopic(i){activeTopic=i;roundNo=1;renderSidebar();startTopic()}
function renderTopicStart(){const t=TOPICS[activeTopic],left=unlearned(t).length;$('#content').innerHTML=`<div class="start"><div class="icon">${mode==='dictation'?'⌨️':'🎯'}</div><h2>${t.name}</h2><p>${left?`Còn <b>${left}</b> / ${t.items.length} từ chưa thuộc. Không giới hạn số từ trong chủ đề; hệ thống sẽ luyện theo vòng cho đến khi bạn đánh dấu hoặc đạt chuỗi đúng 5/5.`:'Bạn đã học thuộc toàn bộ từ trong chủ đề này.'}</p>${left?'<button class="primary" id="startTopic">Bắt đầu</button>':'<div class="mastered-note">✓ Hoàn thành chủ đề</div>'}</div>`;const b=$('#startTopic');if(b)b.onclick=startTopic}
function startTopic(){primeSpeech();queue=shuffle(unlearned(TOPICS[activeTopic]));cursor=0;answered=false;firstAttempt=true;dictWrongThisRound=false;if(!queue.length)return renderTopicStart();renderCurrent()}
function nextCard(){cursor++;answered=false;firstAttempt=true;dictWrongThisRound=false;if(cursor>=queue.length)return renderRoundComplete();renderCurrent()}
function renderRoundComplete(){const t=TOPICS[activeTopic],left=unlearned(t).length;renderSidebar();$('#content').innerHTML=`<div class="complete"><div class="icon">${left?'🔁':'🏆'}</div><h2>${left?'Hoàn thành một vòng!':'Đã thuộc toàn bộ chủ đề!'}</h2><p>${left?`Còn ${left} từ chưa thuộc. Bắt đầu vòng tiếp theo để tiếp tục tích chuỗi đúng 5 lần.`:'Tất cả từ trong chủ đề đã được ẩn khỏi vòng luyện.'}</p>${left?'<button class="primary" id="again">Luyện vòng tiếp theo</button>':''}</div>`;const b=$('#again');if(b)b.onclick=()=>{roundNo++;startTopic()}}
function renderCurrent(){const item=queue[cursor];if(!item)return renderRoundComplete();if(learned.has(item.word))return nextCard();if(mode==='quiz')renderQuiz(item);else renderDictation(item);setTimeout(()=>speak(item.word),90)}
function headerBits(item){const t=TOPICS[activeTopic],left=unlearned(t).length,pct=Math.round((cursor/Math.max(queue.length,1))*100),st=(streaks[mode]?.[item.word]||0);return `<div class="topic-kicker"><span>${t.name} · Vòng ${roundNo}</span><span>Còn ${left} từ</span></div><div class="progress"><i style="width:${pct}%"></i></div><div class="streak">Chuỗi đúng ngay lần đầu: <b>${st} / 5</b></div>`}
function distractors(item){const t=topicOf(item),p=getPos(item),pool=t.items.filter(x=>x.id!==item.id&&!learned.has(x.word));const score=x=>{let s=0;if(getPos(x)===p)s+=6;const a=item.vi.split(/[;,]/)[0].trim(),b=x.vi.split(/[;,]/)[0].trim();s-=Math.abs(a.length-b.length)/15;s-=Math.abs(a.split(' ').length-b.split(' ').length)*.4;return s+Math.random()*.3};const ranked=[...pool].sort((a,b)=>score(b)-score(a));let picks=[];for(const x of ranked){if(!picks.some(y=>norm(y.vi)===norm(x.vi)))picks.push(x);if(picks.length===3)break}if(picks.length<3){const global=DATA.filter(x=>x.id!==item.id&&!picks.includes(x));for(const x of shuffle(global)){if(!picks.some(y=>norm(y.vi)===norm(x.vi)))picks.push(x);if(picks.length===3)break}}return shuffle([item,...picks]).map(x=>x.vi)}
function renderQuiz(item){const opts=distractors(item),letters='ABCD';$('#content').innerHTML=`<div class="hero">${headerBits(item)}<div class="word-card"><div class="word-top"><div><div class="word">${item.word}</div><span class="pos">${getPos(item)}</span></div><button class="speak-btn" id="speak">🔊 Phát âm</button></div><div class="hint">${getHint(item.word)}</div>${strongSynonymHTML(item.word)}${headerBits(item).match(/<div class="streak">.*?<\/div>/)?.[0]||''}</div><div class="answers">${opts.map((v,i)=>`<button class="answer" data-v="${encodeURIComponent(v)}"><span class="badge">${letters[i]}</span><span>${v}</span></button>`).join('')}</div><div class="feedback" id="fb"></div><div class="card-actions"><button class="learn-btn" id="learn">✓ Tôi đã thuộc từ này</button><button class="next-btn" id="next" hidden>Tiếp theo →</button></div></div>`;$('#speak').onclick=()=>speak(item.word);$('#learn').onclick=()=>manualLearn(item);$$('.answer').forEach(b=>b.onclick=()=>answerQuiz(item,b));}
function answerQuiz(item,btn){if(answered)return;answered=true;const chosen=decodeURIComponent(btn.dataset.v),ok=norm(chosen)===norm(item.vi);$$('.answer').forEach(b=>{b.disabled=true;const v=decodeURIComponent(b.dataset.v);if(norm(v)===norm(item.vi))b.classList.add('correct')});if(!ok)btn.classList.add('wrong');const fb=$('#fb');if(ok){stats.quiz.correct++;incrementStreak('quiz',item,true);fb.textContent='✓ Đúng ngay lần đầu.';fb.className='feedback good'}else{stats.quiz.wrong++;incrementStreak('quiz',item,false);fb.textContent=`Chưa đúng. Đáp án đúng: ${item.vi}`;fb.className='feedback bad'}save();if(learned.has(item.word)){fb.textContent='✓ Đúng 5 lần liên tiếp — hệ thống đã tự động đánh dấu Đã thuộc.';fb.className='feedback good';renderSidebar();setTimeout(nextCard,900)}else $('#next').hidden=false;$('#next').onclick=nextCard}
function incrementStreak(kind,item,okFirst){streaks[kind]??={};streaks[kind][item.word]=okFirst?(streaks[kind][item.word]||0)+1:0;if(streaks[kind][item.word]>=5)learned.add(item.word)}
function manualLearn(item){learned.add(item.word);streaks.quiz[item.word]=Math.max(5,streaks.quiz[item.word]||0);streaks.dictation[item.word]=Math.max(5,streaks.dictation[item.word]||0);save();renderSidebar();const fb=$('#fb');if(fb){fb.textContent='✓ Đã đánh dấu thuộc. Từ này sẽ được ẩn khỏi vòng luyện.';fb.className='feedback good'}setTimeout(nextCard,550)}
function charTemplate(word,typed=''){const chars=[...word],t=[...typed];let ti=0;return chars.map(c=>{if(c===' ')return '<span class="letter-box space"></span>';const val=t[ti++]||'';return `<span class="letter-box">${val.replace(/</g,'&lt;')}</span>`}).join('')}
function renderDictation(item){$('#content').innerHTML=`<div class="hero">${headerBits(item)}<div class="word-card"><div class="word-top"><div><div class="dict-meaning">${item.vi}</div><span class="pos">${getPos(item)}</span></div><button class="speak-btn" id="speak">🔊 Phát âm</button></div><div class="spelling-wrap"><div class="spelling-boxes" id="boxes">${charTemplate(item.word)}</div><input class="spell-input" id="spell" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="Nhập từ tiếng Anh..."><button class="primary spell-submit" id="check">Kiểm tra</button></div><div class="feedback" id="fb"></div><div id="reveal"></div><div class="card-actions"><button class="learn-btn" id="learn">✓ Tôi đã thuộc từ này</button><button class="next-btn" id="next" hidden>Tiếp theo →</button></div></div></div>`;const inp=$('#spell');inp.oninput=()=>$('#boxes').innerHTML=charTemplate(item.word,inp.value.replace(/\s/g,''));inp.onkeydown=e=>{if(e.key==='Enter')checkSpelling(item)};$('#check').onclick=()=>checkSpelling(item);$('#speak').onclick=()=>speak(item.word);$('#learn').onclick=()=>manualLearn(item);setTimeout(()=>inp.focus(),120)}
function checkSpelling(item){if(answered)return;const inp=$('#spell'),val=norm(inp.value),target=norm(item.word),fb=$('#fb');if(val===target){answered=true;stats.dictation.correct++;incrementStreak('dictation',item,!dictWrongThisRound);save();fb.textContent=dictWrongThisRound?'✓ Đúng. Lượt này không cộng chuỗi vì đã sai trước đó.':'✓ Đúng ngay lần đầu.';fb.className='feedback good';$('#reveal').innerHTML=`<div class="example-reveal"><b>${item.word}</b> — ${getHint(item.word)}<br><em>${item.example}</em></div>`;inp.disabled=true;$('#check').disabled=true;if(learned.has(item.word)){fb.textContent='✓ Đúng 5 lần liên tiếp — hệ thống đã tự động đánh dấu Đã thuộc.';renderSidebar();setTimeout(nextCard,900)}else{$('#next').hidden=false;$('#next').onclick=nextCard}}else{if(!dictWrongThisRound){stats.dictation.wrong++;incrementStreak('dictation',item,false);dictWrongThisRound=true;save()}fb.textContent='Chưa đúng, thử lại. Chuỗi đúng của từ này đã về 0.';fb.className='feedback bad';inp.select()}}
function shuffleUnlearned(){if(mode==='syn'){synQueue=[];renderSynStart();return}const t=TOPICS[activeTopic],left=unlearned(t).length;if(!left)return renderTopicStart();queue=shuffle(unlearned(t));cursor=0;roundNo=1;answered=false;dictWrongThisRound=false;primeSpeech();renderCurrent()}
function restartAll(){if(!confirm('Học lại toàn bộ sẽ bỏ tất cả dấu Đã thuộc và chuỗi đúng 5 lần. Chủ đề vẫn được giữ nguyên. Tiếp tục?'))return;learned.clear();streaks={quiz:{},dictation:{}};save();renderSidebar();if(mode==='syn')renderSynStart();else renderTopicStart()}
function selectSynLesson(i){synLesson=i;renderSidebar();renderSynStart()}
function renderSynStart(){const lesson=SYN_LESSONS[synLesson];$('#content').innerHTML=`<div class="start"><div class="icon">≈</div><h2>Từ đồng nghĩa · Bài ${String(synLesson+1).padStart(2,'0')}</h2><p>Giữ nguyên cách học cũ: mỗi vòng có 8 thẻ và chỉ có một cặp cùng nghĩa. Chọn thẻ để nghe phát âm và xem English hint.</p><button class="primary" id="synStart">Bắt đầu</button></div>`;$('#synStart').onclick=startSyn}
function startSyn(){primeSpeech();synRound=0;synQueue=shuffle([...Array(SYN_LESSONS[synLesson].length).keys()]);nextSyn()}
function nextSyn(){const lesson=SYN_LESSONS[synLesson];if(synRound>=synQueue.length){$('#content').innerHTML=`<div class="complete"><div class="icon">✨</div><h2>Hoàn thành bài đồng nghĩa!</h2><p>Bạn đã hoàn thành ${lesson.length} cặp.</p><button class="primary" id="synAgain">Chơi lại</button></div>`;$('#synAgain').onclick=startSyn;return}synPair=lesson[synQueue[synRound]];synSelected=[];synLocked=false;const pool=[...new Set(DATA.map(x=>x.word).filter(x=>!synPair.includes(x)))];const opts=shuffle([...synPair,...shuffle(pool).slice(0,6)]);$('#content').innerHTML=`<div class="hero"><div class="round-line"><span>Chọn 2 thẻ cùng nghĩa</span><strong>Vòng ${synRound+1} / ${lesson.length}</strong></div><div class="stats-row"><div class="mini-stat"><span>Đúng</span><b>${stats.syn.correct}</b></div><div class="mini-stat"><span>Sai</span><b>${stats.syn.wrong}</b></div><div class="mini-stat"><span>Bài</span><b>${synLesson+1}</b></div></div><div class="syn-grid">${opts.map(w=>`<button class="syn-card" data-word="${encodeURIComponent(w)}">${w}<span class="speaker">🔊</span></button>`).join('')}</div><div class="feedback" id="fb"></div></div>`;$$('.syn-card').forEach(b=>b.onclick=()=>chooseSyn(b))}
function chooseSyn(btn){if(synLocked)return;const w=decodeURIComponent(btn.dataset.word);if(btn.classList.contains('selected')){btn.classList.remove('selected');const h=btn.querySelector('.syn-hint');if(h)h.remove();synSelected=synSelected.filter(x=>x!==btn);return}speak(w);btn.classList.add('selected');btn.insertAdjacentHTML('beforeend',`<span class="syn-hint">${getHint(w)}</span>`);synSelected.push(btn);if(synSelected.length<2)return;synLocked=true;const words=synSelected.map(b=>decodeURIComponent(b.dataset.word));const ok=synPair.every(x=>words.includes(x));if(ok){stats.syn.correct++;synSelected.forEach(b=>b.classList.add('good'));$('#fb').textContent=`✓ Đúng! ${synPair.join(' = ')}`;$('#fb').className='feedback good';save();synRound++;setTimeout(nextSyn,850)}else{stats.syn.wrong++;synSelected.forEach(b=>b.classList.add('bad'));$('#fb').textContent='Hai từ này chưa cùng nghĩa.';$('#fb').className='feedback bad';save();setTimeout(()=>{synSelected.forEach(b=>{b.classList.remove('selected','bad');const h=b.querySelector('.syn-hint');if(h)h.remove()});synSelected=[];synLocked=false;$('#fb').textContent=''},750)}}
